def check_string(s):
    # Check if the string contains at least one uppercase letter
    if any(char.isupper() for char in s):
        # Check if the string contains at least one lowercase letter
        if any(char.islower() for char in s):
            # Check if the string contains at least one digit
            if any(char.isdigit() for char in s):
                # Check if the string length is at least 8
                if len(s) >= 8:
                    return ['String must have 1 upper case character.', 'String must have 1 number.', 'String length should be atleast 8.']
    return ['String must have 1 upper case character.', 'String must have 1 number.', 'String length should be atleast 8.']
```

