def search_literal(text, pattern):
    # Find the index of the first occurrence of the pattern in the text
    start_index = text.find(pattern)
    # If the pattern is found, return its starting index and length
    if start_index != -1:
        return (start_index, len(pattern))
    else:
        # If the pattern is not found, return -1 for both index and length
        return (-1, -1)
