def longest_increasing_subsequence(nums):
    # Initialize an empty list to store the lengths of increasing subsequences
    dp = [1] * len(nums)

    # Iterate through each number in the sequence
    for i in range(1, len(nums)):
        # Update the length of the longest increasing subsequence ending at the current index
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    # The maximum value in the dp list gives the length of the longest increasing subsequence
    return max(dp)
```

