def assign_elements(tup):
    # Create an empty dictionary to store the result
    result = {}
    # Iterate over the input tuple
    for i in range(len(tup)):
        # Extract the first and second elements of the current tuple
        first = tup[i][0]
        second = tup[i][1]
        # Check if the first element is already a key in the result dictionary
        if first in result:
            # Append the second element to the list associated with the first element
            result[first].append(second)
        else:
            # Add the first element as a key with a list containing the second element
            result[first] = [second]
    return result

