def is_Sub_Array(arr1, arr2, n1, n2):
    # Check if the length of arr2 is greater than n1
    if len(arr2) > n1:
        return False

    # Iterate through arr1 and check if any subarray of arr2 matches arr1
    for i in range(n1):
        for j in range(i, n1 + n2):
            if arr1[i:j] == arr2:
                return True

    return False
