def diff_even_odd(lst):
    # Initialize variables to store the first even and odd numbers
    even = None
    odd = None

    # Iterate through the list to find the first even and odd numbers
    for num in lst:
        if num % 2 == 0:
            even = num
        else:
            odd = num

    # Calculate the difference between the first even and odd numbers
    if even is not None and odd is not None:
        return even - odd
    else:
        return "No even or odd numbers found in the list."
